package com.truckload.controller;
import android.app.*;
import android.graphics.Color;
import android.os.SystemClock;
import android.view.*;
import android.widget.*;
import java.util.*;
/** Native driving, map and supervised bench controls. */
public final class FeaturePanels {
 private final MainActivity a;private final Telemetry m;private final List<Button> extended=new ArrayList<>(),benchOnly=new ArrayList<>();private final Map<String,TextView> labels=new HashMap<>();private final String[] patterns={"SOLID","PULSE","CHASE","ALTERNATE","BREATHE","RAINBOW","COMET","SCANNER","WAVE","AURORA","THEATER"};private SaveFeedback patternFeedback,brightnessFeedback;private Button applyPattern,saveBrightness;private int requestedBrightness=140;private Spinner driveSelect;private SeekBar driveBrightness,loadSlider,psiSlider;private boolean driveDirty=false,loadDragging=false,psiDragging=false,active=true;private long heartbeat=0;private AlertDialog benchDialog;private GpsMapView map;private Button color1,color2,start,stop,realOn,realOff;
 public FeaturePanels(MainActivity activity,Telemetry model){a=activity;m=model;}
 private TextView label(LinearLayout p,String id,String value){TextView t=a.text(value,13,0xffa2b1c4);labels.put(id,t);p.addView(t);return t;}
 private void say(String key,String value){TextView t=labels.get(key);if(t!=null)t.setText(value);}
 private Button feature(String text,Runnable action){Button b=a.button(text,action,false);extended.add(b);return b;}
 private Button benchButton(String text,String command){Button b=feature(text,()->a.send(command));benchOnly.add(b);return b;}
 public void driving(LinearLayout p){
  LinearLayout c=a.card(p,"Driving lights",null);
  label(c,"support","Connect to read driving settings.");c.addView(a.text("Pattern",12,0xffa2b1c4));
  driveSelect=new Spinner(a);String[] titles={"Solid","Gentle pulse","Smooth chase","Crossfade alternating","Breathing","Rainbow","Comet trail","Scanner sweep","Color wave","Aurora","Theater chase"};ArrayAdapter<String> choices=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,titles);choices.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);driveSelect.setAdapter(choices);c.addView(driveSelect);
  patternFeedback=new SaveFeedback(a,c,"Saved on controller");driveSelect.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> parent){}public void onItemSelected(AdapterView<?> parent,View view,int i,long id){if(!patterns[i].equals(m.drivePattern))patternFeedback.edited();}});
  applyPattern=feature("Save pattern",()->{int i=driveSelect.getSelectedItemPosition();if(i>=6&&!m.capabilities.contains("FADE_PATTERNS")){a.notice("Update controller firmware to 0.6.4 for the new patterns.");return;}patternFeedback.saving();a.send("SET_DRIVE_PATTERN|"+patterns[i]);update();});a.selected(applyPattern,true);a.addButton(c,applyPattern);
  a.gap(c,16);label(c,"driveBrightness","Brightness · 55%");driveBrightness=new SeekBar(a);driveBrightness.setMin(1);driveBrightness.setMax(100);c.addView(driveBrightness);brightnessFeedback=new SaveFeedback(a,c,"Saved on controller");driveBrightness.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){}public void onStopTrackingTouch(SeekBar s){}public void onProgressChanged(SeekBar s,int v,boolean user){if(user){driveDirty=true;brightnessFeedback.edited();say("driveBrightness","Brightness · "+v+"%");}}});
  saveBrightness=feature("Save brightness",()->{requestedBrightness=Math.max(1,Math.round(driveBrightness.getProgress()*255f/100f));brightnessFeedback.saving();a.send("SET_DRIVE_BRIGHTNESS|"+requestedBrightness);update();});a.selected(saveBrightness,true);a.addButton(c,saveBrightness);
  a.gap(c,14);c.addView(a.text("Pattern colors",12,0xffa2b1c4));color1=feature("Primary color",()->a.colorDialog(4));color2=feature("Secondary color",()->a.colorDialog(6));a.pair(c,color1,color2);c.addView(a.text("Aurora and rainbow use their own palettes.",12,0xffa2b1c4));
 }
 public void testing(LinearLayout p){a.controllerDetails(p);a.gap(p,10);p.addView(a.text("Temporary light tests and real sensor checks. Closing the tester stops the test.",12,0xffa2b1c4));a.addButton(p,a.button("Open bench tester",this::showBench,false));}
 public void gpsMap(LinearLayout p){LinearLayout c=a.card(p,"GPS map","Blue marks the Heltec. The plant and its geofence are green. Drag to explore; map tiles need internet.");map=new GpsMapView(a);c.addView(map,new LinearLayout.LayoutParams(-1,a.dp(280)));LinearLayout buttons=a.row();a.pair(c,a.button("Zoom in",()->map.zoom(1),false),a.button("Zoom out",()->map.zoom(-1),false));a.addButton(c,a.button("Follow Heltec",()->map.follow(),false));label(c,"coordinates","Waiting for a real GPS fix. No location is simulated.");}
 public void showBench(){if(benchDialog!=null&&benchDialog.isShowing())return;LinearLayout p=a.vertical();p.setPadding(a.dp(18),a.dp(8),a.dp(18),a.dp(8));p.addView(a.text("Test lights and real sensor diagnostics while parked. Simulated load and pressure below are labelled examples and never become real weight readings or calibration points.",13,0xffa2b1c4));label(p,"benchSupport","Connect a controller with bench-test firmware.");start=feature("Start bench test",()->a.send("BENCH|ON"));stop=feature("Stop bench test",()->a.send("BENCH|OFF"));a.pair(p,start,stop);label(p,"benchState","Bench test is off");a.improvementsBench(p);a.pair(p,benchButton("Test load lights","BENCH_LIGHT|LOAD"),benchButton("Test driving lights","BENCH_LIGHT|DRIVE"));a.pair(p,benchButton("Test work lights","BENCH_LIGHT|WORK"),benchButton("All test lights off","BENCH_LIGHT|OFF"));a.gap(p,12);p.addView(a.text("Driving pattern for testing",14,0xffedf3fa));Spinner drive=new Spinner(a);ArrayAdapter<String> adapter=new ArrayAdapter<>(a,android.R.layout.simple_spinner_item,patterns);adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);drive.setAdapter(adapter);drive.setSelection(Math.max(0,Arrays.asList(patterns).indexOf(m.drivePattern)));p.addView(drive);drive.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> v){}public void onItemSelected(android.widget.AdapterView<?> v,View view,int i,long id){if(m.bench&&!patterns[i].equals(m.drivePattern)){a.send("SET_DRIVE_PATTERN|"+patterns[i]);a.send("BENCH_LIGHT|DRIVE");}}});label(p,"benchLoad","SIMULATED load · 50%");loadSlider=new SeekBar(a);loadSlider.setMax(120);loadSlider.setProgress((int)m.benchPercent);p.addView(loadSlider);loadSlider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){loadDragging=true;}public void onStopTrackingTouch(SeekBar s){a.send("BENCH_LOAD|"+s.getProgress());loadDragging=false;}public void onProgressChanged(SeekBar s,int v,boolean user){if(user)say("benchLoad","SIMULATED load · "+v+"%");}});label(p,"benchPsi","SIMULATED pressure · 25 PSI");psiSlider=new SeekBar(a);psiSlider.setMax(100);psiSlider.setProgress((int)m.benchPsi);p.addView(psiSlider);psiSlider.setOnSeekBarChangeListener(new SeekBar.OnSeekBarChangeListener(){public void onStartTrackingTouch(SeekBar s){psiDragging=true;}public void onStopTrackingTouch(SeekBar s){a.send("BENCH_PSI|"+s.getProgress());psiDragging=false;}public void onProgressChanged(SeekBar s,int v,boolean user){if(user)say("benchPsi","SIMULATED pressure · "+v+" PSI");}});label(p,"benchEstimate","Simulated pressure → calibrated estimate: requires a calibrated trailer.");a.gap(p,14);p.addView(a.text("Real wired pressure sensor",17,0xffedf3fa));realOn=benchButton("Read wired sensor","BENCH_SENSOR|ON");realOff=benchButton("Sensor test off","BENCH_SENSOR|OFF");a.pair(p,realOff,realOn);label(p,"realDiagnostics","Real readings are off");p.addView(a.text("Enabling a sensor test does not change your normal sensor setting. Closing this screen, leaving the app or disconnecting stops the test. Firmware also stops tests after 15 seconds without a heartbeat.",12,0xffa2b1c4));ScrollView wrap=new ScrollView(a);wrap.addView(p);benchDialog=new AlertDialog.Builder(a).setTitle("Bench test · temporary").setView(wrap).setNegativeButton("Close / stop test",null).create();benchDialog.setOnDismissListener(d->{if(a.isConnected()&&m.extended)a.send("BENCH|OFF");extended.remove(start);extended.remove(stop);extended.removeAll(benchOnly);benchOnly.clear();loadSlider=psiSlider=null;});benchDialog.show();update();}
 public void update(){if(patternFeedback!=null){patternFeedback.tick();brightnessFeedback.tick();}boolean available=a.isConnected()&&m.extended;if(driveSelect!=null)driveSelect.setEnabled(available&&!patternFeedback.pending);for(Button b:extended){b.setEnabled(available);b.setAlpha(available?1:.45f);}if(labels.get("support")!=null)labels.get("support").setVisibility(available?View.GONE:View.VISIBLE);say("support",!a.isConnected()?"Connect the Heltec to change driving settings.":m.extended?"Driving controls ready":"Firmware update required for driving patterns and bench tests.");say("benchSupport",!a.isConnected()?"Connect the Heltec to run tests.":!m.extended?"Install the companion firmware update to enable tests.":"Settings use the current trailer, colors and lighting patterns.");if(driveBrightness!=null){driveBrightness.setEnabled(available&&!brightnessFeedback.pending);if(!driveDirty){driveBrightness.setProgress(Math.max(1,Math.round(m.driveBrightness*100f/255)));say("driveBrightness","Driving brightness · "+driveBrightness.getProgress()+"%");}}if(applyPattern!=null){applyPattern.setEnabled(available&&!patternFeedback.pending);saveBrightness.setEnabled(available&&!brightnessFeedback.pending);}if(color1!=null){color1.setText("Primary #"+m.colors.get("DRIVE"));color2.setText("Secondary #"+m.colors.get("DRIVE2"));}if(map!=null)map.position(m,a.isConnected());say("coordinates",a.isConnected()&&m.gpsFix?String.format(Locale.US,"Heltec: %.6f, %.6f",m.latitude,m.longitude):"Waiting for a real GPS fix. No location is simulated.");if(benchDialog!=null&&benchDialog.isShowing()){start.setEnabled(available&&!m.bench);stop.setEnabled(available&&m.bench);for(Button b:benchOnly)b.setEnabled(available&&m.bench);loadSlider.setEnabled(available&&m.bench);psiSlider.setEnabled(available&&m.bench);say("benchState",m.bench?"BENCH ACTIVE · "+m.benchMode+" · calibration capture locked":"Bench test is off");if(!loadDragging){loadSlider.setProgress((int)m.benchPercent);say("benchLoad",String.format(Locale.US,"SIMULATED load · %.0f%%",m.benchPercent));}if(!psiDragging){psiSlider.setProgress((int)m.benchPsi);say("benchPsi",String.format(Locale.US,"SIMULATED pressure · %.0f PSI",m.benchPsi));}say("benchEstimate",Double.isFinite(m.benchWeight)?String.format(Locale.US,"SIMULATED estimate: %.0f lb · %.1f%% of target",m.benchWeight,m.benchEstimate):"SIMULATED estimate: add at least two real calibration points to a trailer.");a.improvementsDiagnostics();say("realDiagnostics",!m.bench||!m.benchSensor?"Real sensor test is off":String.format(Locale.US,"REAL sensor: %s\nADC: %s V · sensor: %s V\nPressure: %s PSI",m.sensor,number(m.adcVolts,3),number(m.sensorVolts,3),number(m.psi,1)));a.selected(realOn,m.benchSensor&&m.bench);a.selected(realOff,!m.benchSensor||!m.bench);}}
 private String number(double n,int decimals){return Double.isFinite(n)?String.format(Locale.US,"%."+decimals+"f",n):"—";}
 public void record(String type,String line){
  if(type.equals("DRIVE_CONFIG")&&driveSelect!=null){if(!patternFeedback.dirty&&!patternFeedback.pending)driveSelect.setSelection(Math.max(0,Arrays.asList(patterns).indexOf(m.drivePattern)));patternFeedback.read();brightnessFeedback.read();}
  if(type.equals("CAPS")&&m.extended){if(m.capabilities.contains("FW_INFO"))a.send("GET_FW_INFO");a.send("GET_DRIVE_CONFIG");a.send("GET_BENCH_STATE");}
  if(line.equals("OK|SET_DRIVE_PATTERN"))patternFeedback.confirmed();
  if(line.equals("OK|SET_DRIVE_BRIGHTNESS")){if(brightnessFeedback.pending)m.driveBrightness=requestedBrightness;driveDirty=false;brightnessFeedback.confirmed();}
  if(type.equals("ERR")){patternFeedback.failed();brightnessFeedback.failed();}
 }
 public void tick(){if(active&&a.isConnected()&&m.bench&&benchDialog!=null&&benchDialog.isShowing()&&SystemClock.elapsedRealtime()-heartbeat>4000){heartbeat=SystemClock.elapsedRealtime();a.send("BENCH_HEARTBEAT");}}
 public void active(boolean value){active=value;if(!value&&a.isConnected()&&m.extended)a.send("BENCH|OFF");}
 public void disconnected(){if(patternFeedback!=null){patternFeedback.disconnected();brightnessFeedback.disconnected();driveDirty=brightnessFeedback.dirty;}m.extended=false;m.capsReceived=false;m.capabilities.clear();m.protocolVersion=0;m.firmware="Unavailable (not reported)";m.rawAdc=-1;m.bench=false;m.plant=false;m.plantLat=m.plantLon=Double.NaN;}
 public void close(){if(map!=null)map.close();if(benchDialog!=null)benchDialog.dismiss();}
}
